import{_ as i,a0 as u,w as d,s as m,I as e,x as n,a1 as t,A as p,ao as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const w=JSON.parse('{"title":"如何在終端下以後台模式運行Linux程序 | LCTT x X-CMD","titleTemplate":false,"description":"如何在終端下以後台模式運行Linux程序 | LCTT (201501) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在終端下以後台模式運行Linux程序 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在終端下以後台模式運行Linux程序 | LCTT (201501) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201501/20141204 How To Run Linux Programs From The Terminal In Background Mode","title":"如何在終端下以後台模式運行Linux程序","tag":"201501","desc":""},"relativePath":"201501/20141204 How To Run Linux Programs From The Terminal In Background Mode.md","filePath":"[post].md"}'),l={name:"201501/20141204 How To Run Linux Programs From The Terminal In Background Mode.md"};function s(f,o,T,x,L,g){const r=u("Link");return d(),m("div",null,[o[16]||(o[16]=e("h1",{id:"如何在終端下以後台模式運行linux程序",tabindex:"-1"},[n("如何在終端下以後台模式運行Linux程序 "),e("a",{class:"header-anchor",href:"#如何在終端下以後台模式運行linux程序","aria-label":"Permalink to “如何在終端下以後台模式運行Linux程序”"},"​")],-1)),o[17]||(o[17]=e("p",null,[e("img",{src:"http://0.tqn.com/y/linux/1/W/r/G/1/terminal.JPG",alt:"Linux Terminal Window."})],-1)),o[18]||(o[18]=e("p",null,[e("em",null,"Linux終端窗口")],-1)),o[19]||(o[19]=e("p",null,"這是一個簡短但是非常有用的教程：它向你展示從終端運行Linux應用程序的同時，如何保證終端仍然可以操作。",-1)),o[20]||(o[20]=e("p",null,"在Linux中有許多方式可以打開一個終端，這主要取決於你的發行版的選擇和桌面環境。",-1)),e("p",null,[o[1]||(o[1]=n("使用Ubuntu的話，你可以使用CTRL + ALT + T組合鍵打開一個終端。你也可以點擊超級鍵(Windows鍵)打開一個終端窗口。在鍵盤上，",-1)),t(r,{href:"http://linux.about.com/od/howtos/fl/Learn-Ubuntu-The-Unity-Dash.htm"},{default:p(()=>[...o[0]||(o[0]=[n("打開Ubuntu Dash",-1)])]),_:1}),o[2]||(o[2]=n('，然後搜索"TERM"。點擊"Term"圖標將會打開一個終端窗口。',-1))]),o[21]||(o[21]=a(`<p>其他諸如XFCE, KDE, LXDE, Cinnamon和MATE的桌面環境，你將會在菜單中發現“終端”這個應用。還有一些發行版會把終端圖標放在菜單項，或者在面板上放置終端啓動器。</p><p>你可以在終端裏面輸入一個程序的名字來啓動一個應用。舉例，你可以通過輸入&quot;firefox&quot;啓動火狐瀏覽器。</p><p>從終端運行程序的好處是可以使用額外的選項。</p><p>舉個例子，如果你輸入下面的命令，一個新的火狐瀏覽器將會打開，而且默認的搜索引擎將會搜索引號之間的詞語：</p><pre><code>firefox -search &quot;Linux.About.Com&quot;
</code></pre><p>你會發現，如果你運行火狐瀏覽器，應用程序打開後，控制權將會回到終端（重新出現了命令提示符），這將意味着你可以繼續在終端工作。</p><p>通常情況下，如果你通過終端運行一個程序，程序打開後，並且直到那個程序關閉結束，你都將不會獲得終端的控制權。這是因為你是在前台打開程序的。</p><p>想要從終端運行一個程序，並且立即將終端的控制權返回給你，你需要以後台進程的方式打開程序。</p><p>為了以後台進程的方式打開一個程序，只需要添加符號(&amp;)到命令中，如下面所示：</p><pre><code>libreoffice &amp;
</code></pre><p>在終端中僅僅提供程序的名字，應用程序可能運行不了。如果程序不存在於一個設置在PATH 環境變量的文件夾中，你需要指定完整的路徑名來運行程序。</p><pre><code>/path/to/yourprogram &amp;
</code></pre><p>如果你並不確定一個程序是否存在於Linux文件系統中，使用find或者locate命令來查找該應用程序。</p><p>找一個文件的語法如下：</p><pre><code>find /path/to/start/from -name programname
</code></pre><p>舉個例子，可以使用下面的命令尋找Firefox的位置：</p><pre><code>find / -name firefox
</code></pre><p>輸出會很快滾動出很多，所以你可以以管道的方式控制輸出的多少：</p><pre><code>find / -name firefox | more

find / -name firefox | less
</code></pre><p>find命令將會返回因權限拒絕而發生錯誤的文件夾數量，這些文件夾你沒有權限去搜索。</p><p>你可以使用sudo命令提升你的權限。如果sudo沒有安裝，你需要切換到擁有權限的用户：</p><pre><code>sudo find / -name firefox | more
</code></pre><p>如果你知道你想尋找的文件在你的當前文件夾中，你可以一個點代替先前的斜線，如下：</p><pre><code>sudo find . -name firefox | more
</code></pre><p>你可能不需要sudo來提升權限。如果你在home文件夾中尋找文件，sudo就不需要。</p><p>一些應用程序需要提升用户權限來運行，你可能得到一個缺少權限的錯誤，除非你使用一個具有足夠權限的用户，或者使用sudo提升你的權限。</p><p>下面是一個小花招。如果你運行一個程序，而且它需要提升權限來運行，輸入下面命令來提升權限重新執行：</p><pre><code>sudo !!
</code></pre><hr>`,29)),e("p",null,[o[4]||(o[4]=n("via: ",-1)),t(r,{href:"http://linux.about.com/od/commands/fl/How-To-Run-Linux-Programs-From-The-Terminal-In-Background-Mode.htm"},{default:p(()=>[...o[3]||(o[3]=[n("http://linux.about.com/od/commands/fl/How-To-Run-Linux-Programs-From-The-Terminal-In-Background-Mode.htm",-1)])]),_:1})]),e("p",null,[o[8]||(o[8]=n("作者：",-1)),t(r,{href:"http://linux.about.com/bio/Gary-Newell-132058.htm"},{default:p(()=>[...o[5]||(o[5]=[n("Gary Newell",-1)])]),_:1}),o[9]||(o[9]=n(" 譯者：",-1)),t(r,{href:"https://github.com/su-kaiyao"},{default:p(()=>[...o[6]||(o[6]=[n("su-kaiyao",-1)])]),_:1}),o[10]||(o[10]=n(" 校對：",-1)),t(r,{href:"https://github.com/wxy"},{default:p(()=>[...o[7]||(o[7]=[n("wxy",-1)])]),_:1})]),e("p",null,[o[13]||(o[13]=n("本文由 ",-1)),t(r,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...o[11]||(o[11]=[n("LCTT",-1)])]),_:1}),o[14]||(o[14]=n(" 原創翻譯，",-1)),t(r,{href:"http://linux.cn/"},{default:p(()=>[...o[12]||(o[12]=[n("Linux中> 國",-1)])]),_:1}),o[15]||(o[15]=n(" 榮譽推出",-1))])])}const P=i(l,[["render",s]]);export{w as __pageData,P as default};
